const CB={it:{},nt:0,rb:0,wrap:0,dv:0};
function csbInv(){const L=myLoc(),I=INVL().filter(i=>lq(i,L)>0||CB.it[i.id]),fl=I.filter(i=>!i.cat||/цвет/i.test(i.cat)),ad=I.filter(i=>!fl.includes(i));return{L,fl,ad}}
