  lab=[0,3,6,9,12,15,18,21].map(h=>{const a=(h/24*360-90)*Math.PI/180;return `<text x="${Math.round(500+505*Math.cos(a)*.98)}" y="${Math.round(500+505*Math.sin(a)*.98)+5}" text-anchor="middle">${String(h).padStart(2,"0")}</text>`}).join(""),
