  hand=`<line x1="500" y1="500" x2="${Math.round(500+470*Math.cos((na-90)*Math.PI/180))}" y2="${Math.round(500+470*Math.sin((na-90)*Math.PI/180))}" stroke="currentColor" stroke-width="2" vector-effect="non-scaling-stroke" class="cs-hand"/>`;
